import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { nonprofitCauseSchema, type NonprofitCause } from "./nonprofit-cause.js";

export type Nonprofit = {
  /** The causes that the nonprofit supports. */
  causes: NonprofitCause[];
  /** The description of the nonprofit. */
  description: string;
  /** The goals of the nonprofit. */
  goals: string[];
  /** The unique identifier of the nonprofit organization. This value is generated by Adyen. */
  id?: string;
  /**
   * The locales that the nonprofit supports, in [IETF BCP
   * 47](https://en.wikipedia.org/wiki/IETF_language_tag) format.
   */
  locales: string[];
  /** The URL to the logo of the nonprofit. */
  logoUrl: string;
  /** The name of the nonprofit. */
  name: string;
  /**
   * The regions where the nonprofit operates, in [ISO 3166-1
   * alpha-2](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2) format.
   */
  regions: string[];
  /** The URL to the terms and conditions of the nonprofit. */
  termsAndConditionsUrl: string;
  /** The URL to the website of the nonprofit. */
  website: string;
};

export const nonprofitSchema: Schema<Nonprofit> = s.object<Nonprofit>({
  causes: s.array(s.lazy(() => nonprofitCauseSchema)),
  description: s.string(),
  goals: s.array(s.string()),
  id: s.optional(s.string()),
  locales: s.array(s.string()),
  logoUrl: s.string(),
  name: s.string(),
  regions: s.array(s.string()),
  termsAndConditionsUrl: s.string(),
  website: s.string(),
});
